#include <stdio.h>
#include <stdlib.h>

#define MAX_SIZE 10000

typedef struct Mem {
    int num;
    int count;
} Mem;

int cmp(const void *a, const void *b) {
    Mem *A = *((Mem **) a);
    Mem *B = *((Mem **) b);

    if (A->count != B->count) {
        return B->count - A->count;
    } else {
        return A->num - B->num;
    }
}

int main() {
    int n;
    scanf("%d", &n);

    Mem *mem[MAX_SIZE];
    int mem_size = 0;

    for (int i = 0; i < n; i++) {
        int num;
        scanf("%d", &num);

        int j = 0;
        for (; j < mem_size; j++) {
            if (mem[j]->num == num) {
                mem[j]->count++;
                break;
            }
        }

        if(j < mem_size) continue;

        mem[mem_size] = (Mem *) malloc(sizeof(Mem));
        mem[mem_size]->num = num;
        mem[mem_size]->count = 1;

        mem_size++;
    }

    int threshold;
    scanf("%d", &threshold);

    qsort(mem, mem_size, sizeof(Mem *), cmp);

    int hot_mem_size = mem_size;
    for (int i = 0; i < mem_size; i++) {
        if (mem[i]->count < threshold) {
            hot_mem_size = i;
            break;
        }
    }

    printf("%d\n", hot_mem_size);

    for (int i = 0; i < hot_mem_size; i++) {
        printf("%d\n", mem[i]->num);
    }

    return 0;
}
